class Solution {
public:
    int sumOfPowers(vector<int>& nums, int k) {
        int n = nums.size();
        sort(nums.begin(), nums.end());
        long long MOD = 1e9 + 7;

        map<tuple<int, int, int, int>, int> memo;

        auto dfs = [&](auto& self, int i, int rem, int prev_idx, int min_diff) -> int {
            if (rem == 0) return min_diff == 1e9 ? 0 : min_diff;
            if (i == n || n - i < rem) return 0;

            auto key = make_tuple(i, rem, prev_idx, min_diff);
            if (memo.count(key)) return memo[key];

            long long res = self(self, i + 1, rem, prev_idx, min_diff);
            int new_diff = (prev_idx != -1) ? min(min_diff, nums[i] - nums[prev_idx]) : 1e9;
            res = (res + self(self, i + 1, rem - 1, i, new_diff)) % MOD;

            return memo[key] = res;
        };

        return dfs(dfs, 0, k, -1, 1e9);
    }
};

class Solution {
    private static final int MOD = 1_000_000_007;

    public int sumOfPowers(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        Map<String, Integer> memo = new HashMap<>();
        return dfs(0, k, -1, Integer.MAX_VALUE, nums, memo);
    }

    private int dfs(int i, int rem, int prevIdx, int minDiff, int[] nums, Map<String, Integer> memo) {
        if (rem == 0) return minDiff == Integer.MAX_VALUE ? 0 : minDiff;
        if (i == nums.length || nums.length - i < rem) return 0;

        String key = i + "," + rem + "," + prevIdx + "," + minDiff;
        if (memo.containsKey(key)) return memo.get(key);

        long res = dfs(i + 1, rem, prevIdx, minDiff, nums, memo);
        int newDiff = (prevIdx != -1) ? Math.min(minDiff, nums[i] - nums[prevIdx]) : Integer.MAX_VALUE;
        res = (res + dfs(i + 1, rem - 1, i, newDiff, nums, memo)) % MOD;

        memo.put(key, (int) res);
        return (int) res;
    }
}

var sumOfPowers = function(nums, k) {
    const MOD = 1000000007;
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const memo = new Map();

    function dfs(i, rem, prevIdx, minDiff) {
        if (rem === 0) return minDiff === Infinity ? 0 : minDiff;
        if (i === n || n - i < rem) return 0;

        const key = `${i},${rem},${prevIdx},${minDiff}`;
        if (memo.has(key)) return memo.get(key);

        let res = dfs(i + 1, rem, prevIdx, minDiff);
        const newDiff = (prevIdx !== -1) ? Math.min(minDiff, nums[i] - nums[prevIdx]) : Infinity;
        res = (res + dfs(i + 1, rem - 1, i, newDiff)) % MOD;

        memo.set(key, res);
        return res;
    }

    return dfs(0, k, -1, Infinity);
};
